    document.querySelectorAll('[data-feedback]').forEach(button => button.onclick = async () => { const clip = state.project.clips.find(item => item.id === state.project.selectedClipId) || state.project.clips[0]; if (!clip) return; const type = clip.feedback === button.dataset.feedback ? null : button.dataset.feedback; clip.feedback = type; await fetch(`/api/projects/${state.project.id}/clip-feedback`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ clipId: clip.id, type }) }); render(); toast(type === 'favorite' ? '즐겨찾기에 저장했습니다.' : type === 'like' ? '좋아요를 저장했습니다.' : type === 'dislike' ? '아쉬워요를 저장했습니다.' : '상태를 해제했습니다.'); });
